import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.D7xI0JV8.js";const g=JSON.parse('{"title":"Proof Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"proof-pipeline.md","filePath":"proof-pipeline.md"}'),i={name:"proof-pipeline.md"};function d(n,t,c,l,s,h){return a(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="proof-pipeline" tabindex="-1">Proof Pipeline <a class="header-anchor" href="#proof-pipeline" aria-label="Permalink to &quot;Proof Pipeline&quot;">​</a></h1><p>This is the core proving layer of zkde.fi: a system that can start with fast off-chain verification and escalate to full dual-lane on-chain guarantees depending on the trust requirements of each action.</p><p>Not every action needs the same trust guarantee. A low-stakes advisory check doesn&#39;t require the same proof weight as a high-value vault rebalance. The pipeline supports three modes that trade verification strength for cost and speed — and the system selects the appropriate mode based on policy posture and action type.</p><p>Live proof evidence for all lanes: <strong><a href="https://zkde.fi/test" target="_blank" rel="noreferrer">zkde.fi/test</a></strong></p><h2 id="layered-model" tabindex="-1">Layered Model <a class="header-anchor" href="#layered-model" aria-label="Permalink to &quot;Layered Model&quot;">​</a></h2><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20A%5BProofMode%3A%20execution%20depth%5D%20--%3E%20B%5BVerifier%20lane%3A%20proof%20semantics%5D%0A%20%20B%20--%3E%20C%5BSettlement%20path%3A%20recursive%20propagation%5D%0A%20%20C%20--%3E%20D%5BReceipts%20%2B%20policy%20state%5D%0A%0A%20%20A1%5BEZKL_ONLY%5D%0A%20%20A2%5BEZKL_BRIDGE%5D%0A%20%20A3%5BFULL_DUAL_PROVER%5D%0A%0A%20%20B1%5Bgroth16_garaga%5D%0A%20%20B2%5Bstark_integrity%5D%0A%20%20B3%5Bnoir_honk%5D%0A%20%20B4%5Bnative_kzg%5D%0A%20%20B5%5Bhash_only%20fallback%5D%0A%0A%20%20C1%5BPath%201%3A%20L3%20on-chain%20verify%5D%0A%20%20C2%5BPath%202%3A%20SNOS%20L3%20to%20L2%20validity%5D%0A%20%20C3%5BPath%203%3A%20L3%20on-chain%20aggregation%5D">flowchart LR
  A[ProofMode: execution depth] --&gt; B[Verifier lane: proof semantics]
  B --&gt; C[Settlement path: recursive propagation]
  C --&gt; D[Receipts + policy state]

  A1[EZKL_ONLY]
  A2[EZKL_BRIDGE]
  A3[FULL_DUAL_PROVER]

  B1[groth16_garaga]
  B2[stark_integrity]
  B3[noir_honk]
  B4[native_kzg]
  B5[hash_only fallback]

  C1[Path 1: L3 on-chain verify]
  C2[Path 2: SNOS L3 to L2 validity]
  C3[Path 3: L3 on-chain aggregation]</pre><h2 id="_1-execution-depth-—-proofmode" tabindex="-1">1) Execution Depth — ProofMode <a class="header-anchor" href="#_1-execution-depth-—-proofmode" aria-label="Permalink to &quot;1) Execution Depth — ProofMode&quot;">​</a></h2><p>Source: <code>backend/app/services/proof_mode.py</code></p><table tabindex="0"><thead><tr><th>Mode</th><th>What Happens</th><th>Gas Profile</th><th>When It&#39;s Used</th></tr></thead><tbody><tr><td><code>EZKL_ONLY</code></td><td>EZKL inference runs. Verification is off-chain only. No on-chain proof artifact.</td><td>0 L2 gas</td><td>Fast advisory checks, low-stakes screening, development flows</td></tr><tr><td><code>EZKL_BRIDGE</code></td><td>EZKL output is bound into a bridge circuit (ModelBridge or ModelBridgeHeavy) and proven via Groth16. Garaga verifies the proof on-chain in Cairo.</td><td>~34M L2 gas</td><td>Standard execution gating — on-chain verifiable model output</td></tr><tr><td><code>FULL_DUAL_PROVER</code></td><td>Bridge lane (Groth16/Garaga) <strong>plus</strong> an independent STARK integrity lane via Stone. Two separate proofs for the same action.</td><td>~77M L2 gas</td><td>High-value execution where independent dual-proof verification is required</td></tr></tbody></table><h2 id="_2-verifier-lanes" tabindex="-1">2) Verifier Lanes <a class="header-anchor" href="#_2-verifier-lanes" aria-label="Permalink to &quot;2) Verifier Lanes&quot;">​</a></h2><p>Source: <code>backend/app/services/proof_pipeline.py</code> and <code>l3_proving_path_client.py</code></p><table tabindex="0"><thead><tr><th>Lane</th><th>Circuit / Selector</th><th>L3 Mode</th><th>Status</th><th>Evidence</th></tr></thead><tbody><tr><td>ModelBridge</td><td><code>bridge_circuit=&quot;ModelBridge&quot;</code></td><td><code>groth16_garaga</code></td><td><strong>Live</strong></td><td><a href="https://sepolia.voyager.online/tx/0x2c8ea7551f965f4c73292cd3d00745d088b5572c7154bf6b3746c9f66a0679b" target="_blank" rel="noreferrer">Tx on Voyager</a></td></tr><tr><td>ModelBridgeHeavy</td><td><code>bridge_circuit=&quot;ModelBridgeHeavy&quot;</code></td><td><code>groth16_garaga</code></td><td><strong>Live</strong></td><td><a href="https://sepolia.voyager.online/tx/0x49226ffb495953f1a981020ebb61e8ac462410b750ac672dd21d3f0a8f5b59c" target="_blank" rel="noreferrer">Tx on Voyager</a></td></tr><tr><td>Noir EZKL Bridge</td><td><code>bridge_circuit=&quot;NoirEzklBridge&quot;</code></td><td><code>noir_honk</code></td><td><strong>Live</strong></td><td><a href="https://sepolia.voyager.online/tx/0x55f1d6cf06ed5e2deaf90c86479c2f03b27ed631478447d14af808f33963475" target="_blank" rel="noreferrer">Tx on Voyager</a></td></tr><tr><td>Native EZKL KZG</td><td><code>bridge_circuit=&quot;EzklNativeKzg&quot;</code></td><td><code>native_kzg</code></td><td><strong>Live</strong></td><td><a href="https://sepolia.voyager.online/tx/0x5c9e21abd2119600421872f0baad9988ea7082eec54bacea8657649a8cf5f42" target="_blank" rel="noreferrer">Tx on Voyager</a></td></tr><tr><td>STARK Heavy Reputation</td><td><code>/risk_passport/stark-heavy-reputation</code></td><td><code>stark_integrity</code></td><td><strong>Live</strong></td><td><a href="https://sepolia.voyager.online/tx/0x7249f4a0dc41f12dd5249f4e7284c0f4d392ec69740396d1de4e0f83126739d" target="_blank" rel="noreferrer">Tx on Voyager</a></td></tr></tbody></table><h3 id="core-verification-contracts" tabindex="-1">Core Verification Contracts <a class="header-anchor" href="#core-verification-contracts" aria-label="Permalink to &quot;Core Verification Contracts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Contract</th><th>Address</th><th>Network</th></tr></thead><tbody><tr><td>ModelBridge Verifier</td><td><a href="https://sepolia.voyager.online/contract/0x037c42e8734271aca0c3c1bdf1746d9ccc098ddfd5ee211c94bbb8786fa4626f" target="_blank" rel="noreferrer"><code>0x037c42e8734271aca0c3c1bdf1746d9ccc098ddfd5ee211c94bbb8786fa4626f</code></a></td><td>Starknet Sepolia</td></tr><tr><td>ZkmlVerifier (ModelBridge-capable)</td><td><a href="https://sepolia.voyager.online/contract/0x068abd64a4a78172a5ee15a30bbe614257d62482f07d3ff7fdb72da5aad08923" target="_blank" rel="noreferrer"><code>0x068abd64a4a78172a5ee15a30bbe614257d62482f07d3ff7fdb72da5aad08923</code></a></td><td>Starknet Sepolia</td></tr><tr><td>GaragaVerifier (BN254)</td><td><a href="https://sepolia.voyager.online/contract/0x06d0cb7a48b48c5b6ca70f856d249caccea90f506ad7596a6838502fe3aa6d37" target="_blank" rel="noreferrer"><code>0x06d0cb7a48b48c5b6ca70f856d249caccea90f506ad7596a6838502fe3aa6d37</code></a></td><td>Starknet Sepolia</td></tr><tr><td>Halo2Verifier (EZKL KZG)</td><td><a href="https://sepolia.etherscan.io/address/0xF7b555ca4E54a8c7B9A0DDBFa17341575a852Ab9" target="_blank" rel="noreferrer"><code>0xF7b555ca4E54a8c7B9A0DDBFa17341575a852Ab9</code></a></td><td>Ethereum Sepolia</td></tr></tbody></table><h2 id="_3-signal-to-receipt-lifecycle" tabindex="-1">3) Signal-to-Receipt Lifecycle <a class="header-anchor" href="#_3-signal-to-receipt-lifecycle" aria-label="Permalink to &quot;3) Signal-to-Receipt Lifecycle&quot;">​</a></h2><p>This is the full path from user intent to settled proof:</p><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20SIG%5BSignal%20%2F%20Opportunity%5D%20--%3E%20POL%5BPolicy%20%2B%20gate%20check%5D%0A%20%20POL%20--%3E%20ZKML%5BzkML%20screening%3A%2013%20circuits%5D%0A%20%20ZKML%20--%3E%20ADP%5BAdapter%20route%20selection%5D%0A%20%20ADP%20--%3E%20SIM%5BSimulation%5D%0A%20%20SIM%20--%3E%20TX%5BWallet-signed%20tx%5D%0A%20%20TX%20--%3E%20PROOF%5BProof%20generation%3A%20EZKL%20%E2%86%92%20Bridge%20%E2%86%92%20Garaga%5D%0A%20%20PROOF%20--%3E%20SETTLE%5BSettlement%3A%20Madara%20L3%20or%20Starknet%20L2%5D%0A%20%20SETTLE%20--%3E%20RCPT%5BReceipt%20%2B%20trust%20update%5D">flowchart LR
  SIG[Signal / Opportunity] --&gt; POL[Policy + gate check]
  POL --&gt; ZKML[zkML screening: 13 circuits]
  ZKML --&gt; ADP[Adapter route selection]
  ADP --&gt; SIM[Simulation]
  SIM --&gt; TX[Wallet-signed tx]
  TX --&gt; PROOF[Proof generation: EZKL → Bridge → Garaga]
  PROOF --&gt; SETTLE[Settlement: Madara L3 or Starknet L2]
  SETTLE --&gt; RCPT[Receipt + trust update]</pre><ol><li><strong>Signal arrives</strong> — an opportunity, rebalance trigger, or user action</li><li><strong>Policy gate evaluates</strong> — reputation tier, collateral posture, proof history</li><li><strong>zkML screening runs</strong> — the relevant circuits from the 13-circuit bundle evaluate the action&#39;s risk characteristics</li><li><strong>Route selected</strong> — adapter determines execution path (Ekubo swap, LP, lending, etc.)</li><li><strong>Simulation</strong> — calldata built and simulated before signing</li><li><strong>Proof generated</strong> — depending on ProofMode, EZKL inference → bridge circuit → Garaga verification</li><li><strong>Settlement</strong> — proof registered on Madara L3 via ObsqraFactRegistry (or Starknet L2 fallback)</li><li><strong>Receipt created</strong> — immutable receipt stored in ReceiptRegistry, trust/reputation state updated</li></ol><h2 id="_4-recursive-settlement-paths" tabindex="-1">4) Recursive Settlement Paths <a class="header-anchor" href="#_4-recursive-settlement-paths" aria-label="Permalink to &quot;4) Recursive Settlement Paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>What It Does</th><th>Status</th></tr></thead><tbody><tr><td><strong>Path 1</strong></td><td>Verify proofs on L3 contracts, register facts in ObsqraFactRegistry</td><td><strong>Active production path</strong></td></tr><tr><td><strong>Path 2</strong></td><td>Prove L3 block validity to L2 via SNOS-style recursive flow</td><td>Staged / integration</td></tr><tr><td><strong>Path 3</strong></td><td>Move aggregation semantics on-chain in L3 contracts</td><td>Planned</td></tr></tbody></table><h3 id="settlement-endpoints" tabindex="-1">Settlement Endpoints <a class="header-anchor" href="#settlement-endpoints" aria-label="Permalink to &quot;Settlement Endpoints&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/proofs/sequencer-status</code></td><td>Proof sequencer status</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/aggregation/stats</code></td><td>Aggregation pipeline stats</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/aggregation/madara/health</code></td><td>Madara L3 health check</td></tr></tbody></table><h2 id="_5-runtime-components" tabindex="-1">5) Runtime Components <a class="header-anchor" href="#_5-runtime-components" aria-label="Permalink to &quot;5) Runtime Components&quot;">​</a></h2><pre class="mermaid" data-mermaid-source="flowchart%20TB%0A%20%20UI%5BUI%20Layer%3A%20%2Fprofile%20%2Fagent%20%2Ftrade%5D%0A%20%20INTEL%5BIntelligence%20Layer%3A%20opportunities%2C%20signals%2C%20ranking%5D%0A%20%20EXEC%5BExecution%20Layer%3A%20adapters%2C%20simulation%2C%20wallet%20tx%5D%0A%20%20PROOF%5BProof%20%2B%20settlement%20layer%5D%0A%20%20DATA%5BData%20layer%3A%20receipts%2C%20reputation%2C%20policy%20state%5D%0A%0A%20%20UI%20--%3E%20INTEL%20--%3E%20EXEC%20--%3E%20PROOF%20--%3E%20DATA%20--%3E%20UI">flowchart TB
  UI[UI Layer: /profile /agent /trade]
  INTEL[Intelligence Layer: opportunities, signals, ranking]
  EXEC[Execution Layer: adapters, simulation, wallet tx]
  PROOF[Proof + settlement layer]
  DATA[Data layer: receipts, reputation, policy state]

  UI --&gt; INTEL --&gt; EXEC --&gt; PROOF --&gt; DATA --&gt; UI</pre><table tabindex="0"><thead><tr><th>Component</th><th>Port</th><th>Role</th></tr></thead><tbody><tr><td>zkde backend</td><td><code>:8003</code></td><td>User-facing APIs — trade, policy, profile, privacy, sequencer</td></tr><tr><td>obsqra backend</td><td><code>:8002</code></td><td>Proof aggregation, sequencing, settlement</td></tr><tr><td>Madara proof chain</td><td><code>:9944</code></td><td>Dedicated L3 for proof fact registration</td></tr><tr><td>Frontend</td><td><code>:3001</code></td><td>Next.js app — /agent, /trade, /profile, /vault</td></tr></tbody></table><h2 id="_6-product-unlocks" tabindex="-1">6) Product Unlocks <a class="header-anchor" href="#_6-product-unlocks" aria-label="Permalink to &quot;6) Product Unlocks&quot;">​</a></h2><ul><li>AI guidance becomes <strong>cryptographically gateable execution</strong> — not opaque recommendation text</li><li>Privacy rails (shielded / nullifier / relayer / L3 settlement) can stay private while proving compliance</li><li>Same application flow can shift trust posture by selecting a stronger ProofMode, instead of requiring separate infrastructure</li></ul><h2 id="_7-what-still-needs-to-land" tabindex="-1">7) What Still Needs to Land <a class="header-anchor" href="#_7-what-still-needs-to-land" aria-label="Permalink to &quot;7) What Still Needs to Land&quot;">​</a></h2><ol><li><strong>Path B completion:</strong> Universal <code>kzg_mpcheck_v1</code> witness extraction + live strict-mode pass receipts (sidecar/extractor hooks wired; remaining work is robust automatic extraction coverage)</li><li><strong>Path A hardening:</strong> Recurring HONK receipts plus gas/latency benchmark cadence</li><li><strong>Path 2 and 3 rollout:</strong> Full recursive closure from L3 → L2 → L1</li></ol><hr><p>Next: <a href="/docs/privacy-rails.html">Privacy Rails</a> | <a href="/docs/zkml-circuits.html">zkML + Circuit Stack</a> | <a href="/docs/proof-readout.html">Live Proof Readout</a></p>`,31)])])}const f=e(i,[["render",d]]);export{g as __pageData,f as default};
